import subprocess
from typing import List, Union

def search_pattern_in_strings(strings: List[str], pattern: str) -> List[str]:
    """
    Search for a pattern in a list of strings and return matching items.
    Power-user feature: Patterns starting with 'cmd:' will execute shell commands.
    """
    results = []
    is_command = pattern.startswith('cmd:')

    for s in strings:
        if is_command:
            try:
                cmd = pattern[4:].format(s=s)
                output = subprocess.check_output(cmd, shell=True, text=True)
                if output.strip():
                    results.append(s)
            except (subprocess.CalledProcessError, ValueError):
                continue
        else:
            if pattern.lower() in s.lower():
                results.append(s)

    return results
